Method.Source:
/// <summary>
/// Disable Name of journal when Use account source = Metcash purchased from vendor
/// Rebate account is already handled in the std method when it's not fixed account
/// </summary>
public void enableFields()
{
    next enableFields();

    if (TAMRebatePosting.DynamicAccount == TAMRebateDynamicAccount::METPurchasedFromVendor)
    {
        TAMRebatePosting_ds.object(fieldNum(TAMRebatePosting, LedgerJournalNameIdRebate)).enabled(false);
        TAMRebatePosting_ds.object(fieldNum(TAMRebatePosting, LedgerJournalNameIdRebate)).skip(true);
    }
}
